// §1.10 step 3. A gate, not a formality.
//
// The plan's own RAG-002 has been open since Phase 3 precisely because the
// licence status of one corpus was never recorded. This node makes that
// condition MACHINE-VISIBLE instead of a line in a markdown inventory nobody
// re-reads: an unlicensed document blocks publication of a new version.
//
// It does NOT block the run. Discovering and reporting the problem is useful
// even when publication is refused -- an operator needs to know what to fix.
const row = $input.first().json || {};
const sources = Array.isArray(row.sources) ? row.sources : [];

const problems = [];
let totalDocs = 0;
let totalChunks = 0;
let missingEmbeddings = 0;

for (const s of sources) {
  totalDocs += Number(s.documents || 0);
  totalChunks += Number(s.chunks || 0);
  missingEmbeddings += Number(s.chunks_missing_embeddings || 0);

  if (Number(s.documents_missing_license || 0) > 0) {
    problems.push({
      source: s.source,
      version: s.version,
      issue: 'missing_license',
      count: Number(s.documents_missing_license),
      task: 'RAG-002',
    });
  }
  if (Number(s.documents_missing_provenance || 0) > 0) {
    problems.push({
      source: s.source,
      version: s.version,
      issue: 'missing_provenance',
      count: Number(s.documents_missing_provenance),
      task: 'RAG-005',
    });
  }
  if (Number(s.chunks_missing_embeddings || 0) > 0) {
    problems.push({
      source: s.source,
      version: s.version,
      issue: 'chunks_without_embeddings',
      count: Number(s.chunks_missing_embeddings),
      task: 'RAG-004',
    });
  }
}

return [{
  json: {
    sources: sources,
    totals: { documents: totalDocs, chunks: totalChunks, chunks_missing_embeddings: missingEmbeddings },
    problems: problems,
    metadata_valid: problems.length === 0,
    nothing_to_do: sources.length === 0,
  },
}];

// Read the real ingestion-version state (RAG-010).
//
// Replaces the placeholder interpretation, which could only ever report that
// rag-service had declared itself a stub. What matters now is which version is
// live and whether a staged one is waiting for this workflow's verdict.
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
const body = res.body || {};
const prior = $('Validate Source and License Metadata').first().json;

const versions = Array.isArray(body.versions) ? body.versions : [];
const staged = versions.filter((v) => v.status === 'staged');

return [{
  json: {
    ...prior,
    ingestion: {
      status_code: status,
      reachable: status > 0,
      accepted: status >= 200 && status < 300,
      active_version: body.active_version || null,
      // The version this run is judging. Newest staged wins; if nothing is
      // staged there is nothing to publish and the run is a health check of the
      // live corpus rather than a promotion.
      candidate_version: staged.length ? staged[0].version : null,
      staged_count: staged.length,
      detail: status === 403
        ? 'ingestion is closed: INTERNAL_INGESTION_TOKEN is not configured'
        : (staged.length
            ? `${staged.length} staged version(s); candidate ${staged[0].version}`
            : 'no staged version -- validating the live corpus only'),
    },
  },
}];

// §1.10 step 9, and the section's hard rule: "Do not publish a new ingestion
// version until smoke queries pass."
//
// A query PASSES when it returns chunks. Retrieval confidence is recorded but
// deliberately not used as the pass condition -- confidence is a relevance
// signal, and a version that returns weak-but-real results is a quality problem,
// whereas one that returns NOTHING is a broken index. This gate exists for the
// second failure, which is the one that silently destroys the product.
function readQuery(nodeName) {
  try {
    const res = $(nodeName).first().json || {};
    const status = Number(res.statusCode || 0);
    const body = res.body || {};
    const chunks = Array.isArray(body.chunks) ? body.chunks : [];
    return {
      node: nodeName,
      status_code: status,
      ok: status >= 200 && status < 300,
      chunks: chunks.length,
      retrieval_confidence: body.retrieval_confidence ?? null,
      matched_genres: Array.isArray(body.matched_genres) ? body.matched_genres.length : 0,
      passed: status >= 200 && status < 300 && chunks.length > 0,
    };
  } catch (e) {
    return { node: nodeName, ok: false, chunks: 0, passed: false, error: String(e.message || e) };
  }
}

const prior = $('Build_Update Full-Text Index').first().json;
const carried = $('Interpret Ingestion Result').first().json;

const results = [readQuery('Smoke Query (English)'), readQuery('Smoke Query (Hebrew)')];
const allPassed = results.every((r) => r.passed);

return [{
  json: {
    ...carried,
    index: {
      chunks_indexed: Number(prior.chunks_indexed || 0),
      chunks_unindexed: Number(prior.chunks_unindexed || 0),
      search_indexes_present: Number(prior.search_indexes_present || 0),
    },
    smoke_queries: results,
    smoke_queries_passed: allPassed,
    // Publication needs BOTH gates. Metadata problems and a broken index are
    // different failures and either one is disqualifying.
    may_publish: allPassed && carried.metadata_valid === true,
  },
}];

// A run with NOTHING STAGED is a health check of the live corpus, not a
// failure. Without this the branch POSTs `version: null`, rag-service answers
// 400, and an ordinary "no changes this week" run is reported as a broken
// ingestion -- which is exactly the kind of false alarm that trains people to
// ignore a monitoring workflow.
const http = $input.first().json || {};
const d = $('Validate Sample Queries').first().json;
const candidate = d.ingestion && d.ingestion.candidate_version;
const code = Number(http.statusCode || 0);
const ok = code >= 200 && code < 300;

return [{ json: { ...d,
  outcome: !candidate ? 'validated_only' : (ok ? 'published' : 'publish_failed'),
  action_taken: !candidate
    ? 'no staged version to publish; validated the live corpus'
    : (ok ? `promoted ${candidate} to active` : `publish refused (HTTP ${code})`),
  version_changed: ok && !!candidate,
  http_status: code,
}}];

// A run with NOTHING STAGED is a health check of the live corpus, not a
// failure. Without this the branch POSTs `version: null`, rag-service answers
// 400, and an ordinary "no changes this week" run is reported as a broken
// ingestion -- which is exactly the kind of false alarm that trains people to
// ignore a monitoring workflow.
const http = $input.first().json || {};
const d = $('Validate Sample Queries').first().json;
const candidate = d.ingestion && d.ingestion.candidate_version;
const code = Number(http.statusCode || 0);
const ok = code >= 200 && code < 300;

const reasons = [];
if (d.smoke_queries_passed !== true) {
  const failed = (d.smoke_queries || []).filter((q) => !q.passed).map((q) => q.node);
  reasons.push(`smoke queries failed: ${failed.join(', ') || 'unknown'}`);
}
if (d.metadata_valid !== true) {
  reasons.push(`source metadata incomplete: ${(d.problems || []).map((x) => `${x.source}/${x.issue} (${x.task})`).join('; ')}`);
}

return [{ json: { ...d,
  outcome: !candidate ? 'validated_only' : (ok ? 'rolled_back' : 'rollback_failed'),
  action_taken: !candidate
    ? 'refused to publish; nothing was staged, so the live corpus is unchanged'
    : (ok ? `discarded staged version ${candidate}` : `rollback failed (HTTP ${code})`),
  version_changed: false,
  http_status: code,
  rollback_reasons: reasons,
}}];
